201	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
202	async function* streamRound(
203	  provider: AIProvider,
204	  request: SendMessageParams,
205	  pendingToolCalls: ToolCall[]
206	): AsyncGenerator<MessageChunk, RoundOutcome> {
207	  let stopReason = '';
208	  let text = '';
209	  let usage: UsageMetadata | undefined;
210	
211	  for await (const chunk of provider.sendMessage(request)) {
212	    yield chunk;
213	    collectToolCalls(chunk, pendingToolCalls);
214	    stopReason = extractStopReason(chunk) ?? stopReason;
215	    usage = extractUsage(chunk) ?? usage;
216	    if (chunk.type === 'text') text += chunk.text;
217	  }
218	
219	  return {stopReason, text, usage};
220	}
