1	import {createChatOrchestrator} from './chatOrchestrator.js';
2	import type {OrchestratorHooks} from './chatOrchestrator.js';
3	import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
4	import type {ChatSession} from '../types/session.js';
5	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
6	import {ToolRegistry} from './tools/registry.js';
7	
8	// Issue #93: afterModelResponse is handed the usage of every provider call in the turn, not the last round's alone.
9	
10	// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
11	const SENT_AT = '2026-01-01T00:00:00.000Z';
12	
13	const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
14	
15	const createSession = (content: string): ChatSession => ({
16	  sessionId: 's1',
17	  userId: 'u1',
18	  entries: [{role: 'user', content, timestamp: SENT_AT}],
