1	// Every fenced typescript block in a documented file is generated from source, not transcribed.
2	
3	// Hand transcription is how the repo shipped a wrong frame order, a field name that
4	// never existed and three config keys that are not read. A marker names where a block
5	// comes from; --fix rewrites the block from there.
6	
7	import {readFileSync, writeFileSync} from 'node:fs';
8	import {execFileSync} from 'node:child_process';
9	import {join} from 'node:path';
10	import process from 'node:process';
11	import {root} from './lib/repo-root.mjs';
12	
13	const USAGE =
14	  'usage: check-doc-blocks.mjs [--fix]\n\nmarkers, on the line before the fence:\n  <!-- doc-block: src/types/ai.ts#AIProvider -->   an exported declaration\n  <!-- doc-block: example/server.ts#quick-start --> a #region span in a checked example\n  <!-- doc-block: none -- reason -->                opt out, reason required';
15	
16	const DOCS = [
17	  'README.md',
18	  'CLAUDE.md',
19	  '.specify/spec.md',
20	  'docs/getting-started.md',
21	  'docs/adding-a-tool.md',
22	  'docs/adding-a-message-type.md',
23	  'docs/coding-practices.md',
24	  'specs/hal-engine-architecture/spec.md',
25	  'specs/hal-engine-providers/spec.md',
26	  'specs/hal-engine-tool-responses/spec.md',
27	  'specs/hal-engine-thinking-tag-parser/spec.md',
28	];
29	
30	// A spike records what was believed when it was written, and its status block says which claims no
31	// longer hold. Its blocks are opted out wholesale rather than one marker at a time: the reason is
32	// the same for every block in the file, it is already written in the status block that
33	// check-spike-status.mjs requires, and 34 copies of it would be 34 places to drift. What is checked
34	// here is the opposite risk - a spike block wired to live source would regenerate spike code from
35	// the implementation that superseded it, quietly erasing the record.
36	const SPIKES = [
37	  'docs/spikes/adding-tool-evaluation.md',
38	  'docs/spikes/mcp.md',
39	  'docs/spikes/spike-ai-response-validation.md',
40	  'docs/spikes/spike-bedrock-integration.md',
41	];
42	
43	// example/ imports the source tree; a reader installs the package.
44	const IMPORT_REWRITES = [[/from '\.\.\/src\/index\.js'/g, "from '@re-cinq/hal-engine'"]];
45	
46	// Every spelling a renderer treats as TypeScript, plus any info string after it: accepting only one
47	// spelling let a block keep its marker, stop being compared, and still render as code. The fence is
48	// read as CommonMark writes it - three or more backticks or tildes, up to three spaces of indent,
49	// closed only by the same character at least as long - because four backticks, a tilde fence and a
50	// fence indented inside a list all render as code and all passed a gate that saw only ```.
51	const OPEN_FENCE = /^( {0,3})(`{3,}|~{3,})[ \t]*(typescript|ts|tsx)\b[^`]*$/i;
52	const ANY_CLOSE = /^ {0,3}(`{3,}|~{3,})[ \t]*$/;
53	const closes = (line, marker) => {
54	  const match = ANY_CLOSE.exec(line);
55	  return match !== null && match[1][0] === marker[0] && match[1].length >= marker.length;
56	};
57	const MARKER = /^<!-- doc-block: (.+?) -->$/;
58	
59	const args = process.argv.slice(2);
60	const fix = args.includes('--fix');
61	if (args.some(a => a !== '--fix')) {
62	  process.stderr.write(`${USAGE}\n`);
63	  process.exit(2);
64	}
65	
66	const read = path => readFileSync(join(root, path), 'utf8');
67	const trimEnd = text =>
68	  text
69	    .split('\n')
70	    .map(line => line.replace(/\s+$/, ''))
71	    .join('\n')
72	    .replace(/\n+$/, '');
73	
74	function declaration(path, name) {
75	  const source = read(path);
76	  const start = source.search(new RegExp(`^export (?:interface|type|class|function|const) ${name}\\b`, 'm'));
77	  if (start < 0) return {error: `no exported declaration named ${name} in ${path}`};
78	
79	  const rest = source.slice(start);
80	  const firstBrace = rest.indexOf('{');
81	  const semicolon = rest.indexOf(';');
82	
83	  // `type X = 'a' | 'b';` has no brace, so a bare semicolon terminates it.
84	  if (firstBrace < 0 || (semicolon >= 0 && semicolon < firstBrace)) {
85	    return {text: rest.slice(0, semicolon + 1).replace(/^export /, '')};
86	  }
87	
88	  let depth = 0;
89	  for (let i = firstBrace; i < rest.length; i += 1) {
90	    if (rest[i] === '{') depth += 1;
91	    if (rest[i] === '}') depth -= 1;
92	    if (depth === 0) return {text: rest.slice(0, i + 1).replace(/^export /, '')};
93	  }
94	  return {error: `unbalanced braces reading ${name} from ${path}`};
95	}
96	
97	function region(path, name) {
98	  const lines = read(path).split('\n');
99	  const open = lines.findIndex(l => l.trim() === `// #region ${name}`);
100	  if (open < 0) return {error: `no "// #region ${name}" in ${path}`};
101	
102	  const close = lines.findIndex((l, i) => i > open && l.trim() === '// #endregion');
103	  if (close < 0) return {error: `"// #region ${name}" in ${path} is never closed`};
104	
105	  const body = lines.slice(open + 1, close);
106	  const indents = body.filter(l => l.trim()).map(l => l.match(/^ */)[0].length);
107	  const dedent = indents.length > 0 ? Math.min(...indents) : 0;
108	  let text = body.map(l => l.slice(dedent)).join('\n');
109	  for (const [pattern, replacement] of IMPORT_REWRITES) text = text.replace(pattern, replacement);
110	  return {text};
111	}
112	
113	function expected(marker) {
114	  const [path, name] = marker.split('#');
115	  if (!path || !name) return {error: `marker "${marker}" is not path#name`};
116	  return path.startsWith('example/') ? region(path, name) : declaration(path, name);
117	}
118	
119	const findings = [];
120	let rewritten = 0;
121	let spikeBlocks = 0;
122	
123	for (const doc of SPIKES) {
124	  const lines = read(doc).split('\n');
125	
126	  for (let i = 0; i < lines.length; i += 1) {
127	    if (!OPEN_FENCE.test(lines[i])) continue;
128	    spikeBlocks += 1;
129	
130	    const marker = (lines[i - 1] ?? '').trim().match(MARKER);
131	    if (marker && marker[1].split(' -- ')[0] !== 'none') {
132	      findings.push(`${doc}:${i} a spike block names a source; its code is the record, not the implementation`);
133	    }
134	  }
135	}
136	
137	for (const doc of DOCS) {
138	  const lines = read(doc).split('\n');
139	  let changed = false;
140	
141	  // Driven from the marker as well as the fence: widening the recognised set left the bypass open,
142	  // because relabelling a block ```js keeps the marker, stops the comparison, and still renders as code.
143	  for (let i = 0; i < lines.length; i += 1) {
144	    if (!MARKER.test(lines[i].trim())) continue;
145	    if (OPEN_FENCE.test(lines[i + 1] ?? '')) continue;
146	    findings.push(`${doc}:${i + 1} doc-block marker is not followed by a typescript fence`);
147	  }
148	
149	  for (let i = 0; i < lines.length; i += 1) {
150	    const fence = OPEN_FENCE.exec(lines[i]);
151	    if (!fence) continue;
152	    const [, indent, marker] = fence;
153	
154	    const close = lines.findIndex((l, j) => j > i && closes(l, marker));
155	    if (close < 0) {
156	      findings.push(`${doc}:${i + 1} typescript block is never closed`);
157	      continue;
158	    }
159	    const previous = (lines[i - 1] ?? '').trim();
160	    const match = previous.match(MARKER);
161	
162	    if (!match) {
163	      findings.push(`${doc}:${i + 1} typescript block carries no doc-block marker`);
164	      continue;
165	    }
166	
167	    const [optOut, reason] = match[1].split(' -- ');
168	    if (optOut === 'none') {
169	      if (!reason || !reason.trim()) findings.push(`${doc}:${i + 1} opt-out carries no reason`);
170	      continue;
171	    }
172	
173	    const {text, error} = expected(match[1]);
174	    if (error) {
175	      findings.push(`${doc}:${i + 1} ${error}`);
176	      continue;
177	    }
178	
179	    // A fence indented inside a list indents its content too; CommonMark strips up to that indent.
180	    const dedent = new RegExp(`^ {0,${indent.length}}`);
181	    const actual = trimEnd(
182	      lines
183	        .slice(i + 1, close)
184	        .map(l => l.replace(dedent, ''))
185	        .join('\n')
186	    );
187	    if (actual === trimEnd(text)) continue;
188	
189	    if (!fix) {
190	      findings.push(`${doc}:${i + 1} block does not match ${match[1]}`);
191	      continue;
192	    }
193	
194	    const generated = trimEnd(text)
195	      .split('\n')
196	      .map(l => (l ? indent + l : l));
197	    lines.splice(i + 1, close - i - 1, ...generated);
198	    changed = true;
199	    rewritten += 1;
200	  }
201	
202	  if (changed) writeFileSync(join(root, doc), lines.join('\n'));
203	}
204	
205	// A document in neither list is ungated, whatever it holds: the lists are hand-maintained, so a new
206	// guide with a typescript block was covered only if somebody remembered. Fixture documents are the
207	// other gates' inputs and say nothing about this package.
208	const covered = new Set([...DOCS, ...SPIKES]);
209	for (const doc of trackedMarkdown()) {
210	  if (covered.has(doc)) continue;
211	  if (!read(doc).split('\n').some(line => OPEN_FENCE.test(line))) continue;
212	  findings.push(`${doc} holds a typescript block but is in neither DOCS nor SPIKES of check-doc-blocks.mjs`);
213	}
214	
215	if (fix) {
216	  process.stdout.write(`check-doc-blocks: rewrote ${rewritten} block(s)\n`);
217	}
218	
219	for (const finding of findings) process.stdout.write(`  ${finding}\n`);
220	process.stdout.write(
221	  `check-doc-blocks: ${findings.length} finding(s) across ${DOCS.length} documents, plus ${spikeBlocks} block(s) in ${SPIKES.length} spikes\n`
222	);
223	process.exit(findings.length > 0 ? 1 : 0);
224	
225	// Outside a repository there is nothing tracked, and so nothing ungated; the tests run in one.
226	function trackedMarkdown() {
227	  try {
228	    const out = execFileSync('git', ['ls-files', '*.md', ':!scripts/fixtures/**'], {
229	      cwd: root,
230	      encoding: 'utf8',
